# moderngl — iOS: Metal-backed core implementation (via Blender's gpu module).
#
# Historically this was a pure import-stub (every call raised
# NotImplementedError, "iOS has no OpenGL"). It is now a working subset:
# the bundled Blender ships an offscreen **Metal** backend with a runtime
# GLSL->MSL cross-compiler, and _mgl_metal.py adapts moderngl's object model
# onto it. Standalone contexts, buffers, vertex+fragment programs, uniforms,
# VAOs (incl. index buffers), framebuffer render/clear/read, and RGBA8/RGBA32F
# textures run on the Apple GPU for real.
#
# Not supported (clear errors): geometry/tessellation/compute shaders,
# transform feedback, queries, texture arrays/3D/cube. See docs/moderngl.md.

__version__ = "5.12.0+metal_ios"

from ._mgl_metal import (  # noqa: F401
    Error,
    NOTHING, POINTS, LINES, LINE_LOOP, LINE_STRIP,
    TRIANGLES, TRIANGLE_STRIP, TRIANGLE_FAN,
    BLEND, DEPTH_TEST, CULL_FACE,
    Buffer, Program, Texture, VertexArray, Framebuffer, Context,
    create_context, create_standalone_context,
)

# Extra GL constants some callers reference
LINES_ADJACENCY = 10
LINE_STRIP_ADJACENCY = 11
TRIANGLES_ADJACENCY = 12
TRIANGLE_STRIP_ADJACENCY = 13
NEAREST = 9728
LINEAR = 9729
CLAMP_TO_EDGE = 33071
REPEAT = 10497


class _NotImplementedStub:
    def __init__(self, *a, **k):
        raise NotImplementedError(
            f"moderngl.{type(self).__name__} is not supported on the iOS "
            "Metal backend (no geometry/compute shaders, queries, or "
            "texture arrays). Core rendering — Context / Program / Buffer / "
            "VertexArray / Framebuffer / Texture — works; see "
            "docs/moderngl.md.")


class Renderbuffer(_NotImplementedStub): pass          # noqa: E701
class Uniform(_NotImplementedStub): pass               # noqa: E701
class Attribute(_NotImplementedStub): pass             # noqa: E701
class Scope(_NotImplementedStub): pass                 # noqa: E701
class Query(_NotImplementedStub): pass                 # noqa: E701
class Sampler(_NotImplementedStub): pass               # noqa: E701
class ComputeShader(_NotImplementedStub): pass         # noqa: E701
class TextureArray(_NotImplementedStub): pass          # noqa: E701
class Texture3D(_NotImplementedStub): pass             # noqa: E701
class TextureCube(_NotImplementedStub): pass           # noqa: E701


def get_context():
    raise Error("get_context: create one with "
                "moderngl.create_standalone_context() first")


def __getattr__(name):
    # Permissive fallback so `from moderngl import X` in third-party code
    # doesn't die at import time; using the object raises clearly.
    class _Missing(_NotImplementedStub):
        pass
    _Missing.__name__ = name
    return _Missing
